import type { Request, Response } from 'express'
import { stringify } from 'csv-stringify/sync'
import { listCustomersForExport } from './repository'

// 管理画面の「CSVエクスポート」ボタンから呼ばれる。
export async function exportCustomersCsv(req: Request, res: Response) {
  const customers = await listCustomersForExport({ includeArchived: req.query.archived === '1' })
  const csv = stringify(customers.map((c) => [c.id, c.name, c.email, c.createdAt.toISOString().slice(0, 10)]), {
    header: true,
    columns: ['顧客ID', '氏名', 'メールアドレス', '登録日'],
  })
  const date = new Date().toISOString().slice(0, 10)
  res.setHeader('Content-Type', 'text/csv')
  res.setHeader('Content-Disposition', `attachment; filename="customers-${date}.csv"`)
  res.send(csv)
}

// 請求書PDF。日本語が豆腐(□)にならないよう Noto Sans JP を埋め込む。
const FONT = path.join(__dirname, '../../../assets/fonts/NotoSansJP-Regular.ttf')

export async function renderInvoicePdf(invoice: Invoice): Promise<Buffer> {
  const doc = new PDFDocument({ size: 'A4', margin: 48 })
  doc.registerFont('jp', FONT).font('jp')
  doc.fontSize(18).text(`請求書 ${invoice.number}`)
  doc.fontSize(11).text(`${invoice.customerName} 様`)
  ...
}

// 顧客名は全角で最大20文字。長い名前は省略表示にする(文字化けではなく幅の問題)。
export function NameCell({ name }: { name: string }) {
  return <td className="max-w-[20em] truncate" title={name}>{name}</td>
}

