export function sendCsv(res: Response, filename: string, rows: unknown[][], columns: string[]) {
  // Windows 版 Excel は BOM がないと CP932 として読むので、UTF-8 + BOM で返す
  const csv = stringify(rows, { header: true, columns, bom: true })
  res.setHeader('Content-Type', 'text/csv; charset=utf-8')
  res.setHeader('Content-Disposition', `attachment; filename="${filename}"`)
  res.send(csv)
}

// 1万行以上のエクスポートはジョブでファイルを作り、署名付きURLをメールで送る。
export async function runLargeExport(job: ExportJob) {
  const stream = createWriteStream(tmpPath(job))
  const stringifier = stringify({ header: true, columns: COLUMNS[job.kind] })
  stringifier.pipe(stream)
  for await (const row of iterateRows(job)) stringifier.write(row)
  stringifier.end()
  await finished(stream)
  await uploadAndMail(job, tmpPath(job), 'text/csv')
}
